from pathlib import Path
import base64, zlib

FILES = {
    'app/src/main/java/com/tayson/ps4linksender/MainActivity.kt': '',
    'app/src/main/java/com/tayson/ps4linksender/ps4/ReceiverClient.kt': '',
    'app/src/main/java/com/tayson/ps4linksender/storage/AppStore.kt': '',
    'app/src/main/java/com/tayson/ps4linksender/model/Models.kt': '',
    'app/src/main/java/com/tayson/ps4linksender/util/Format.kt': '',
    'app/build.gradle.kts': '',
}

for rel, payload in FILES.items():
    p = Path(rel)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(zlib.decompress(base64.b64decode(payload)))
    print(f"wrote {rel} ({p.stat().st_size} bytes)")
